m"><?= ui_icon('trash') ?></button></div><?php endforeach; ?></div><template data-item-template><div class="request-item"><label>Equipment<select name="equipment_id[]" required><option value="">Select equipment</option><?php foreach($equipment as $e): ?><option value="<?= $e['id'] ?>" data-available="<?= (int)$e['available_quantity'] ?>"><?= esc($e['asset_code'].' · '.$e['name'].' ('.$e['available_quantity'].' available)') ?></option><?php endforeach; ?></select></label><label>Quantity<input type="number" name="quantity[]" min="1" value="1" required></label><button class="icon-button remove-item" type="button" data-remove-item aria-label="Remove item"><?= ui_icon('trash') ?></button></div></template><div class="form-actions"><a class="btn" href="<?= site_url('borrow-requests') ?>">Cancel</a><button class="btn primary" type="submit">Submit Request</button></div></form><?= $this->endSection() ?>
